/* PLAN 063/064 (Lead r19/r19b, kontinuiteten blått->ritning). Den
   LÄGSTA av kapitlets EGNA textrader (live, samma yta latchTick redan
   läser för CASES nedan) jämförs mot --band-h: när den passerar är
   konturarket redan osynligt ovanför skärmen - bytet till
   position:fixed syns aldrig, bara att arket "landar om" en gång
   till på RÄTT ställe (--fz-t/l/w/h, samma tal som .process-stick
   pinnar vid).
   Lead r19b, andra fyndet: utlösaren läste bara RUBRIKENS underkant,
   inte .process-locked ("Webbdesign, design och system...") som
   sitter UNDER den och rensar SENARE - arket fick fixed position
   medan den paragrafen ännu stod kvar i vägen. Paragrafen (som
   rubriken) saknar egen bakgrund (ingen background-regel i CSS) -
   till skillnad från .step-band, som TÄCKER arket med sin egen
   opaka background:var(--bg), lämnar ostyrd text bara GLYFERNA
   mörka och resten av sin box genomskinlig, så arkets kontur sken
   igenom i mellanrummen (uppmätt: elementFromPoint gav rätt topp-
   element, ändå syntes linjen - boxen täcker, inte hela ytan).
   Utlösaren läser nu den SENARE av de två (process-locked om den
   finns, annars rubriken), så frysningen väntar tills BÅDA rensat.
   data-gone tonar bort det frysta arket när griden faktiskt syns.
   chAct.cur < .30 (under landningströskeln .36, med marginal)
   återställer båda om besökaren skrollar tillbaka upp. */
if (processChapterEl && tesPlaneEl && processTitleEl){
  var chAct = findAct(acts, processChapterEl);
  if (!chAct || isNaN(chAct.cur)){
    again = true;
  } else {
    if (!planeFrozen){
      var clearEl = processLockedEl || processTitleEl;
      if (clearEl.getBoundingClientRect().bottom <= planeBandH){
        planeFrozen = true;
        tesPlaneEl.toggleAttribute('data-frozen', true);
      }
    }
    if (planeFrozen){
      /* Both grenar (nyss fryst OCH redan fryst) landar här i SAMMA
         varv nu (två `if`, inte if/else) - en tidigare if/else-version
         satte data-frozen och väntade till NÄSTA bildruta med att
         räkna --fz-clip-b, vilket gav en bildrutas oklippt fullhöjd
         (uppmätt: 1 träff, 1440, scrollY 7404 - exakt frysögonblicket)
         innan klippningen hann komma ikapp.
         Släpp först när sticken FAKTISKT pinnat (dess egen
         margin-top:band-h håller den kvar på gridTop+bandH tills
         skrollen tar ifatt - gridTop<=0 ensamt slog till ~46-55px
         för tidigt, uppmätt med verify_continuity.py). */
      var stTop = processStickEl ? processStickEl.getBoundingClientRect().top : 9999;
      var gone = stTop <= planeBandH + 2;
      if (gone !== planeGone){ planeGone = gone; tesPlaneEl.toggleAttribute('data-gone', gone); }
      if (!gone){
        /* PLAN 063, andra fyndet (geometrisk kontroll). Full arkhöjd
           är INTE säker hela frysfönstret: stegtexten "Uppstart"
           (ännu opinnad, normalt flöde) glider upp genom exakt samma
           yta - de två fönstren delar ingen scrollposition med hela
           höjden fri (uppmätt, find_safe_window.py). Klipp underkanten
           till vad som verkligen är ledigt ovanför närmsta stegband,
           om bildruta - arket växer nerifrån i takt med att platsen
           faktiskt öppnas. */
        var fzBottom = planeFzTop + planeFzH;
        /* Mobil (rad ~1571): sticken staplas FÖRE texten i normalt
           flöde (order:-1, inget grid-area-lager), inte band-h-
