chapterEl.style.setProperty('--pl-h', planeH.toFixed(1) + 'px');
/* PLAN 063, fynd denna runda: .process-sheet byter till 320/200
   under 768 (rad ~1640, K3-registret) - 495/880 var hårdkodat
   obetingat sedan plan 062, aldrig fel synligt förrän frysmålet
   jämfördes pixel mot pixel med det riktiga arket (±11px fel vid
   390, verify_continuity.py). Samma brytpunkt som CSS:n. */
var sheetAspect = window.innerWidth < 768 ? 200 / 320 : 495 / 880;
var pW = x4 - x1;
var pH = pW * sheetAspect;
var planeTop = C.top - planeH;
var landingY = T.top - 40;
var pTop = landingY - pH;
chapterEl.style.setProperty('--pl-t', Math.max(0, pTop - planeTop).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-r', Math.max(0, window.innerWidth - x4).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-l', Math.max(0, x1).toFixed(1) + 'px');
/* PLAN 063. Fryslägets mål: SAMMA bredd/höjd som redan validerats
   mot arket (pW/pH ovan), positionerad vid EXAKT den viewport-Y
   .process-stick faktiskt pinnar vid. Under 768 sätter mobilregeln
   (rad ~1571) .process-stick{top:0;margin-top:0} - --band-h
   används INTE där (upptäckt live: en ovillkorlig läsning av
   --band-h gav 200px+ på mobil och fryste arket mitt i tomma
   luften, uppmätt med verify_continuity.py).
   .process-stick är själv flex/align-items:center - arket CENTRERAS
   i sticken, det landar inte i dess överkant (upptäckt live: en
   första version som bara använde --band-h gav 9px fel vid 1920,
   202px fel vid 768, där sticken är mycket högre än det bredd-
   begränsade arket). Läser stickens EGNA padding/höjd (statisk
   CSS, sann oavsett om den faktiskt pinnat än) för att räkna ut
   SAMMA centrering arket landar i. */
processStickEl = process.querySelector('.process-stick');
planeBandH = window.innerWidth < 768 ? 0 :
  (parseFloat(getComputedStyle(process).getPropertyValue('--band-h')) || 0);
var fzTop = planeBandH;
if (processStickEl){
  var stickCs = getComputedStyle(processStickEl);
  var stickH = parseFloat(stickCs.height) || 0;
  var padT = parseFloat(stickCs.paddingTop) || 0;
  var padB = parseFloat(stickCs.paddingBottom) || 0;
  var centerOff = Math.max(0, (stickH - padT - padB - pH) / 2);
  fzTop = planeBandH + padT + centerOff;
}
chapterEl.style.setProperty('--fz-t', fzTop.toFixed(1) + 'px');
chapterEl.style.setProperty('--fz-l', Math.max(0, x1).toFixed(1) + 'px');
chapterEl.style.setProperty('--fz-w', pW.toFixed(1) + 'px');
chapterEl.style.setProperty('--fz-h', pH.toFixed(1) + 'px');
planeFzTop = fzTop;
planeFzH = pH;
processStepTitleEls = Array.prototype.slice.call(
  process.querySelectorAll('.process-step-title'));
processChapterEl = chapterEl;
processTitleEl = titleEl;
processLockedEl = chapterEl.querySelector('.process-locked');
tesPlaneEl = process.querySelector('.tes-plane');
/* B3: den blå delen finns bara där det blå är tomt. 0 om < 64px
   eller om linjen x krockar tickstrecken ±16px, annars
   min(fri - 32, 22svh). */
if (stageEl){
  var tickRects = [];
  for (var ki = 0; ki < tickEls.length; ki++) tickRects.push(tickEls[ki].getBoundingClientRect());
  var xs = [x1, x2, x3, x4];

