from playwright.sync_api import sync_playwright
import json, os

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
OUT = "C:/Users/Anton L/anti-slop-design/tests/alunix-r8/runs/V3d/shots/r21"
os.makedirs(OUT, exist_ok=True)

CHECK_JS = """
() => {
  const plane = document.querySelector('.tes-plane');
  const cs = getComputedStyle(plane);
  const rect = plane.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0 || parseFloat(cs.opacity) < 0.02) return {visible:false};
  const m = /^inset\\(([^)]+)\\)/.exec(cs.clipPath);
  let top=rect.top, right=rect.right, bottom=rect.bottom, left=rect.left;
  if (m) {
    const raw = m[1].trim().split(/\\s+/);
    function val(tok, base) { return tok.endsWith('%') ? parseFloat(tok)/100*base : parseFloat(tok); }
    let it,ir,ib,il;
    if (raw.length===1){it=ir=ib=il=val(raw[0],rect.height);}
    else if (raw.length===2){it=ib=val(raw[0],rect.height);ir=il=val(raw[1],rect.width);}
    else if (raw.length===3){it=val(raw[0],rect.height);ir=il=val(raw[1],rect.width);ib=val(raw[2],rect.height);}
    else {it=val(raw[0],rect.height);ir=val(raw[1],rect.width);ib=val(raw[2],rect.height);il=val(raw[3],rect.width);}
    top=rect.top+it; bottom=rect.bottom-ib; left=rect.left+il; right=rect.right-ir;
    if (left>=right || top>=bottom) return {visible:false};
  }
  function isOpaque(el){
    const c = getComputedStyle(el).backgroundColor;
    const mm = /rgba?\\(([^)]+)\\)/.exec(c);
    if (!mm) return false;
    const parts = mm[1].split(',').map(s=>parseFloat(s));
    const a = parts.length>3?parts[3]:1;
    return a>=0.98;
  }
  function hasOwnText(el){
    if (!(el.tagName==='P'||el.tagName==='H3'||el.tagName==='H2'||el.tagName==='SPAN'||el.tagName==='A')) return false;
    for (const n of el.childNodes) if (n.nodeType===3 && n.textContent.trim().length) return true;
    return false;
  }
  function checkPoint(x,y){
    const stack = document.elementsFromPoint(x,y);
    const idx = stack.findIndex(e=>e.classList && e.classList.contains('tes-plane'));
    if (idx===-1) return null;
    for (let i=idx+1;i<stack.length;i++){
      const el = stack[i];
      if (hasOwnText(el)) return {x:Math.round(x),y:Math.round(y),text:el.tagName+':'+el.textContent.trim().slice(0,25)};
      if (isOpaque(el)) return null;
    }
    return null;
  }
  const findings = [];
  const N=10;
  for (let i=0;i<=N;i++){
    const x = left + (right-left)*i/N;
    let f=checkPoint(x, top+1); if (f) findings.push(f);
    f=checkPoint(x, bottom-1); if (f) findings.push(f);
  }
  for (let i=0;i<=N;i++){
    const y = top + (bottom-top)*i/N;
    let f=checkPoint(left+1, y); if (f) findings.push(f);
    f=checkPoint(right-1, y); if (f) findings.push(f);
  }
  // also: is .tes-plane still position:absolute (never fixed)?
  const posOk = cs.position !== 'fixed';
  return {visible:true, top, bottom, left, right, findings, position: cs.position, posOk};
}
"""

def run(w, h):
    with sync_playwright() as p:
        b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(300)
        ch = pg.evaluate("""() => {
          const el = document.querySelector('.process-chapter');
          const r = el.getBoundingClientRect();
          return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
        }""")
        grid = pg.evaluate("""() => {
          const g = document.querySelector('.process-grid');
          const r = g.getBoundingClientRect();
          return r.top + window.scrollY;
        }""")
        start = max(0, ch['top'] - ch['vh'])
        end = grid + 600
        pg.evaluate("(y) => window.scrollTo(0, y)", start)
        pg.wait_for_timeout(200)
        all_findings = []
        fixed_seen = False
        y = start
        frames = 0
        # down
        while y <= end:
